DO $gf$
DECLARE f regprocedure;
BEGIN
  FOR f IN SELECT p.oid::regprocedure FROM pg_proc p WHERE p.pronamespace = 'authz_gen'::regnamespace
           AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"app.folders:rules:explain"', '"app.folders:update:items"', '"app.folders:update:refuse"', '"app.folders:update:why"', '"app.inbox:insert:items"', '"app.inbox:insert:refuse"', '"app.inbox:insert:why"', '"app.inbox:rules:explain"', '"app.notes:delete:items"', '"app.notes:delete:why"', '"app.notes:insert:items"', '"app.notes:insert:refuse"', '"app.notes:insert:why"', '"app.notes:rules:explain"', '"app.notes:update:items"', '"app.notes:update:refuse"', '"app.notes:update:why"', '"app.projects:rules:explain"']::text[]) LOOP
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I', f, 'conf_app');
  END LOOP;
END $gf$;

